def StrongestExtension(class_name, extensions):
   strongest_extension = extensions[0]
   for i, extension in enumerate(extensions):
       cap = len(extension.upper())
       sm = len(extension.lower())
       if cap - sm > strongest_extension[1]:
           strongest_extension = (extension, i)
   return class_name + "." + strongest_extension[0]

def StrongestExtension(class_name, extensions):
   strongest_extension = extensions[0]
   for extension in extensions[1:]:
       if len(extension) > len(strongest_extension):
           strongest_extension = extension
   return f"{class_name}.{strongest_extension}"

